  icono: "⚙️",                     // emoji simple, funciona como ícono liviano sin dependencias
  investigado: false,              // true = datos verificados con fuentes; false = ficha base sin inventar cifras
  duracionAnios: null,             // número o null
  cargaHoraria: null,              // texto o null
  queHace: "",                     // ¿Qué hace ese profesional?
  problemasQueResuelve: "",
  perfilRecomendado: "",
  habilidades: [],
  materiasPrincipales: [],
  dificultad: "",                  // texto corto: "Media", "Alta", etc. con justificación breve
  especializaciones: [],
  salidasLaborales: [],
  empresasArgentinas: [],
  organismosPublicos: [],
  trabajoIndependiente: "",
  trabajoRemoto: "",
  trabajoExterior: "",
  demandaActual: "",
  proyeccion: "",
  herramientas: [],
  ventajas: [],
  desafios: [],
  datosInteresantes: [],
  experienciaPersonal: "",         // el estudiante la completa a mano
